package com.mad.edt.colleague.llm;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A single message exchanged with a language model. Besides plain text this
 * covers assistant tool requests and tool execution results.
 */
public final class ChatMessage {

    /** Instruction that configures assistant behavior. */
    public static final String ROLE_SYSTEM = "system";
    /** Message authored by the end user. */
    public static final String ROLE_USER = "user";
    /** Message generated by the model. */
    public static final String ROLE_ASSISTANT = "assistant";
    /** Result of a tool execution fed back to the model. */
    public static final String ROLE_TOOL = "tool";

    private final String role;
    private final String content;
    private final List<ToolCall> toolCalls;
    private final String toolCallId;

    private ChatMessage(final String theRole, final String theContent, final List<ToolCall> theToolCalls,
        final String theToolCallId) {
        if(theRole == null || theRole.isEmpty()) {
            throw new IllegalArgumentException("message role is empty");
        }
        role = theRole;
        content = theContent == null ? "" : theContent;
        toolCalls = theToolCalls == null
            ? Collections.emptyList()
            : Collections.unmodifiableList(new ArrayList<>(theToolCalls));
        toolCallId = theToolCallId;
    }

    /**
     * Creates a system message.
     *
     * @param theContent message text
     * @return the message
     */
    public static ChatMessage system(final String theContent) {
        return new ChatMessage(ROLE_SYSTEM, theContent, null, null);
    }

    /**
     * Creates a user message.
     *
     * @param theContent message text
     * @return the message
     */
    public static ChatMessage user(final String theContent) {
        return new ChatMessage(ROLE_USER, theContent, null, null);
    }

    /**
     * Creates an assistant message.
     *
     * @param theContent message text
     * @return the message
     */
    public static ChatMessage assistant(final String theContent) {
        return new ChatMessage(ROLE_ASSISTANT, theContent, null, null);
    }

    /**
     * Creates an assistant message that requests tool execution.
     *
     * @param theContent optional accompanying text, may be {@code null}
     * @param theToolCalls requested calls
     * @return the message
     */
    public static ChatMessage assistantToolCalls(final String theContent, final List<ToolCall> theToolCalls) {
        return new ChatMessage(ROLE_ASSISTANT, theContent, theToolCalls, null);
    }

    /**
     * Creates a tool execution result message.
     *
     * @param theToolCallId identifier of the call being answered, may be
     *        {@code null} for providers without call identifiers
     * @param theContent tool output
     * @return the message
     */
    public static ChatMessage toolResult(final String theToolCallId, final String theContent) {
        return new ChatMessage(ROLE_TOOL, theContent, null, theToolCallId);
    }

    /**
     * @return the author role
     */
    public String getRole() {
        return role;
    }

    /**
     * @return the message text, never {@code null}
     */
    public String getContent() {
        return content;
    }

    /**
     * @return requested tool calls, empty for all non-assistant-tool messages
     */
    public List<ToolCall> getToolCalls() {
        return toolCalls;
    }

    /**
     * @return identifier of the call this message answers, may be {@code null}
     */
    public String getToolCallId() {
        return toolCallId;
    }

    /**
     * @return {@code true} when the message carries tool calls
     */
    public boolean hasToolCalls() {
        return !toolCalls.isEmpty();
    }

    @Override
    public String toString() {
        return role + ": " + content + (hasToolCalls() ? " " + toolCalls : "");
    }
}
